// AuthServiceHandler is an implementation of the vx.v1.AuthService service.
type AuthServiceHandler interface {
	WhoAmI(context.Context, *connect.Request[v1.WhoAmIRequest]) (*connect.Response[v1.WhoAmIResponse], error)
	// CreateAgent creates an agent that acts for the caller and returns its token.
	CreateAgent(context.Context, *connect.Request[v1.CreateAgentRequest]) (*connect.Response[v1.CreateAgentResponse], error)
	// ListAgents lists the caller's agents with a summary of their tokens.
	// Only people have agents.
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	// ListTokens lists the tokens of the caller or of one of the caller's
	// agents. Secrets are never returned.
	ListTokens(context.Context, *connect.Request[v1.ListTokensRequest]) (*connect.Response[v1.ListTokensResponse], error)
	// RevokeToken revokes a token of the caller or of one of the caller's
	// agents. Revoking the token the request is made with needs allow_current.
	RevokeToken(context.Context, *connect.Request[v1.RevokeTokenRequest]) (*connect.Response[v1.RevokeTokenResponse], error)
	// CreateToken issues a new token to the caller or to one of the caller's
	// agents. Only people can create tokens: a leaked agent token must not be
	// able to mint replacements that outlive its revocation.
	CreateToken(context.Context, *connect.Request[v1.CreateTokenRequest]) (*connect.Response[v1.CreateTokenResponse], error)
	// CreateLoginCode returns a one-time code that signs the caller in to the
	// web UI (vx ui). It expires after two minutes and works once.
	CreateLoginCode(context.Context, *connect.Request[v1.CreateLoginCodeRequest]) (*connect.Response[v1.CreateLoginCodeResponse], error)
	// GetAgent returns an agent with its path scope, budgets and today's
	// usage. An agent may read its own (agent empty), a person their agents',
	// a superadmin anyone's.
	GetAgent(context.Context, *connect.Request[v1.GetAgentRequest]) (*connect.Response[v1.GetAgentResponse], error)
	// SetAgentScope changes an agent's path scope and budgets. Only the
	// agent's person or a superadmin may; an agent cannot, not even its own.
	SetAgentScope(context.Context, *connect.Request[v1.SetAgentScopeRequest]) (*connect.Response[v1.SetAgentScopeResponse], error)
}

