// OrgServiceClient is a client for the vx.v1.OrgService service.
type OrgServiceClient interface {
	CreateOrg(context.Context, *connect.Request[v1.CreateOrgRequest]) (*connect.Response[v1.CreateOrgResponse], error)
	ListOrgs(context.Context, *connect.Request[v1.ListOrgsRequest]) (*connect.Response[v1.ListOrgsResponse], error)
	GetOrg(context.Context, *connect.Request[v1.GetOrgRequest]) (*connect.Response[v1.GetOrgResponse], error)
	UpdateOrg(context.Context, *connect.Request[v1.UpdateOrgRequest]) (*connect.Response[v1.UpdateOrgResponse], error)
	// Deleting an organization (owners, never agents; not personal ones): it
	// is hidden at once (its repositories are not found, it leaves every
	// list, its handle stays reserved), owners restore it until the grace
	// period ends, then the server purges it. The deletion record names no
	// repository: owners read it until the purge.
	DeleteOrg(context.Context, *connect.Request[v1.DeleteOrgRequest]) (*connect.Response[v1.DeleteOrgResponse], error)
	RestoreOrg(context.Context, *connect.Request[v1.RestoreOrgRequest]) (*connect.Response[v1.RestoreOrgResponse], error)
	GetOrgDeletion(context.Context, *connect.Request[v1.GetOrgDeletionRequest]) (*connect.Response[v1.GetOrgDeletionResponse], error)
	ListDeletedOrgs(context.Context, *connect.Request[v1.ListDeletedOrgsRequest]) (*connect.Response[v1.ListDeletedOrgsResponse], error)
	SetMember(context.Context, *connect.Request[v1.SetMemberRequest]) (*connect.Response[v1.SetMemberResponse], error)
	RemoveMember(context.Context, *connect.Request[v1.RemoveMemberRequest]) (*connect.Response[v1.RemoveMemberResponse], error)
	CreateTeam(context.Context, *connect.Request[v1.CreateTeamRequest]) (*connect.Response[v1.CreateTeamResponse], error)
	DeleteTeam(context.Context, *connect.Request[v1.DeleteTeamRequest]) (*connect.Response[v1.DeleteTeamResponse], error)
	SetTeamMember(context.Context, *connect.Request[v1.SetTeamMemberRequest]) (*connect.Response[v1.SetTeamMemberResponse], error)
	RemoveTeamMember(context.Context, *connect.Request[v1.RemoveTeamMemberRequest]) (*connect.Response[v1.RemoveTeamMemberResponse], error)
	GrantRepo(context.Context, *connect.Request[v1.GrantRepoRequest]) (*connect.Response[v1.GrantRepoResponse], error)
	RevokeRepo(context.Context, *connect.Request[v1.RevokeRepoRequest]) (*connect.Response[v1.RevokeRepoResponse], error)
	RepoAccess(context.Context, *connect.Request[v1.RepoAccessRequest]) (*connect.Response[v1.RepoAccessResponse], error)
	// Support access (repository admins): give a superadmin read or write on
	// one repository until a time, at most 30 days ahead; recorded in the
	// operation log. The superadmin may also end their own early.
	GrantSupport(context.Context, *connect.Request[v1.GrantSupportRequest]) (*connect.Response[v1.GrantSupportResponse], error)
	RevokeSupport(context.Context, *connect.Request[v1.RevokeSupportRequest]) (*connect.Response[v1.RevokeSupportResponse], error)
	ListSupport(context.Context, *connect.Request[v1.ListSupportRequest]) (*connect.Response[v1.ListSupportResponse], error)
	// People (superadmins): create people and list everyone on the server.
	CreatePerson(context.Context, *connect.Request[v1.CreatePersonRequest]) (*connect.Response[v1.CreatePersonResponse], error)
	ListPeople(context.Context, *connect.Request[v1.ListPeopleRequest]) (*connect.Response[v1.ListPeopleResponse], error)
	// The data processing agreement (servers with VX_REQUIRE_DPA): an
	// organization's status, every acceptance and, on request, a version's
	// text (members and superadmins). Accepting is not in the API: an owner
	// accepts in the web UI, as a deliberate act by a person.
	GetOrgAgreement(context.Context, *connect.Request[v1.GetOrgAgreementRequest]) (*connect.Response[v1.GetOrgAgreementResponse], error)
}

